/**
 * Same-tick request batcher — a mini dataloader.
 *
 * `load(key)` calls issued within the same microtask window are coalesced
 * into a single `batchFn(keys)` invocation. Results fan back out to the
 * individual callers, duplicates are deduplicated before reaching batchFn,
 * per-key errors reject only their own caller, and an optional memoization
 * cache serves repeat keys across batches without hitting batchFn again.
 */

export type BatchFn<K, V> = (keys: K[]) => Promise<V[]>;

export interface Loader<K, V> {
  /** Load a single key. Coalesces with other same-tick loads. */
  load(key: K): Promise<V>;
  /** Load many keys in one shot; resolves with an aligned array. */
  loadMany(keys: K[]): Promise<V[]>;
  /** Drop a key from the memoization cache so it re-batches next time. */
  clear(key: K): void;
  /** Drop all cached keys. */
  clearAll(): void;
  /** Prime the cache for a key (skips future batchFn hits). */
  prime(key: K, value: V): void;
}

interface PendingEntry<K> {
  key: K;
  resolve: (value: unknown) => void;
  reject: (reason: unknown) => void;
}

export function createLoader<K, V>(batchFn: BatchFn<K, V>): Loader<K, V> {
  const cache = new Map<K, V>();
  let queue: PendingEntry<K>[] = [];
  // Unique keys of the current pending queue -> first queue index.
  let scheduled = false;

  function dispatch(): void {
    scheduled = false;
    const pending = queue;
    queue = [];

    if (pending.length === 0) return;

    // Deduplicate keys while remembering where each unique key must fan out.
    const uniqueKeys: K[] = [];
    const fanout = new Map<K, number[]>();
    for (let i = 0; i < pending.length; i++) {
      const entry = pending[i];
      let idx = fanout.get(entry.key);
      if (idx === undefined) {
        idx = uniqueKeys.length;
        uniqueKeys.push(entry.key);
        fanout.set(entry.key, [i]);
      } else {
        fanout.get(entry.key)!.push(i);
      }
    }

    let resultsPromise: Promise<V[]>;
    try {
      resultsPromise = Promise.resolve(batchFn(uniqueKeys));
    } catch (err) {
      // Synchronous throw from batchFn behaves like a rejected promise:
      // every caller in this batch fails.
      for (const entry of pending) entry.reject(err);
      return;
    }

    resultsPromise.then(
      (results) => {
        if (!Array.isArray(results) || results.length !== uniqueKeys.length) {
          const err = new Error(
            `batchFn must resolve an array of length ${uniqueKeys.length} (got ${
              Array.isArray(results) ? results.length : typeof results
            }), aligned with the input keys`
          );
          for (const entry of pending) entry.reject(err);
          return;
        }
        for (let u = 0; u < uniqueKeys.length; u++) {
          const value = results[u];
          const key = uniqueKeys[u];
          cache.set(key, value);
          for (const i of fanout.get(key)!) {
            const entry = pending[i];
            if (value instanceof Error) entry.reject(value);
            else entry.resolve(value);
          }
        }
      },
      (err) => {
        // Whole-batch failure rejects every caller in this tick's batch.
        for (const entry of pending) entry.reject(err);
      }
    );
  }

  async function loadUncached(key: K): Promise<V> {
    return new Promise<V>((resolve, reject) => {
      queue.push({ key, resolve, reject });
      if (!scheduled) {
        scheduled = true;
        // Drain at end of the current microtask window: everything queued
        // synchronously up to this point lands in one batch.
        queueMicrotask(dispatch);
      }
    });
  }

  function load(key: K): Promise<V> {
    if (cache.has(key)) return Promise.resolve(cache.get(key)!);
    return loadUncached(key);
  }

  async function loadMany(keys: K[]): Promise<V[]> {
    return Promise.all(keys.map((key) => load(key)));
  }

  function clear(key: K): void {
    cache.delete(key);
  }

  function clearAll(): void {
    cache.clear();
  }

  function prime(key: K, value: V): void {
    cache.set(key, value);
  }

  return { load, loadMany, clear, clearAll, prime };
}

