import { describe, it, expect, vi } from 'vitest';
import { createLoader } from '../src/index';

const flush = () => new Promise<void>((r) => setTimeout(r, 0));
const tick = () => new Promise<void>((r) => setTimeout(r, 0));

describe('createLoader', () => {
  it('coalesces same-tick loads into one deduplicated batchFn call', async () => {
    const batchFn = vi.fn(async (keys: string[]) =>
      keys.map((k) => `value:${k}`)
    );
    const loader = createLoader(batchFn);

    // Schedule several loads synchronously, including duplicates.
    const promises = [
      loader.load('a'),
      loader.load('b'),
      loader.load('a'),
      loader.load('c'),
      loader.load('b'),
      loader.load('a'),
    ];

    expect(batchFn).toHaveBeenCalledTimes(0); // not yet dispatched

    await flush();

    expect(batchFn).toHaveBeenCalledTimes(1);
    // Deduplicated before hitting batchFn.
    expect(batchFn).toHaveBeenCalledWith(['a', 'b', 'c']);

    // Every caller resolves, including duplicate ones.
    expect(await Promise.all(promises)).toEqual([
      'value:a',
      'value:b',
      'value:a',
      'value:c',
      'value:b',
      'value:a',
    ]);
  });

  it('loadMany is sugar that batches and aligns results with keys', async () => {
    const batchFn = vi.fn(async (keys: number[]) => keys.map((k) => k * 10));
    const loader = createLoader(batchFn);

    const result = await loader.loadMany([3, 1, 2, 3]);

    expect(result).toEqual([30, 10, 20, 30]);
    expect(batchFn).toHaveBeenCalledTimes(1);
    expect(batchFn).toHaveBeenCalledWith([3, 1, 2]);
  });

  it('a per-key Error in results rejects only that caller', async () => {
    const boom = new Error('boom');
    const batchFn = vi.fn(async (keys: string[]) =>
      keys.map((k) => (k === 'bad' ? boom : `ok:${k}`))
    );
    const loader = createLoader(batchFn);

    const pGood = loader.load('good');
    const pBad = loader.load('bad');
    const pAlsoBad = loader.load('bad'); // duplicate of a failing key

    await expect(pBad).rejects.toBe(boom);
    await expect(pAlsoBad).rejects.toBe(boom);
    await expect(pGood).resolves.toBe('ok:good');

    // A whole-batch rejection rejects everyone too.
    const failing = createLoader<string, string>(async () => {
      throw new Error('total meltdown');
    });
    await expect(failing.load('x')).rejects.toThrow('total meltdown');
    await expect(failing.load('y')).rejects.toThrow('total meltdown');
  });

  it('cache hits skip batchFn until cleared', async () => {
    const batchFn = vi.fn(async (keys: string[]) => keys.map((k) => k.toUpperCase()));
    const loader = createLoader(batchFn);

    await loader.load('key'); // batch #1

    const hit = loader.load('key'); // served from cache, no batching
    await expect(hit).resolves.toBe('KEY');
    expect(batchFn).toHaveBeenCalledTimes(1);

    // clear(key) evicts so the next load re-batches.
    loader.clear('key');
    const second = loader.load('key'); // batch #2
    await flush();
    expect(batchFn).toHaveBeenCalledTimes(2);
    expect(batchFn).toHaveBeenLastCalledWith(['key']);
    await expect(second).resolves.toBe('KEY');

    loader.clearAll();
    await loader.load('other');
    expect(batchFn).toHaveBeenCalledTimes(3);
  });

  it('loads on two separate ticks produce two separate batches', async () => {
    const batchFn = vi.fn(async (keys: string[]) => keys.map((k) => `${k}!`));
    const loader = createLoader(batchFn);

    const firstTick = [loader.load('x'), loader.load('y')];
    await tick();
    expect(batchFn).toHaveBeenCalledTimes(1);

    // New tick: fresh microtask window, fresh batch.
    const secondTick = [loader.load('y'), loader.load('z')];
    await tick();

    expect(batchFn).toHaveBeenCalledTimes(2);
    expect(batchFn).toHaveBeenNthCalledWith(1, ['x', 'y']);
    expect(batchFn).toHaveBeenNthCalledWith(2, ['z']); // 'y' still cached from batch 1? No—cache covers it.

    expect(await Promise.all(firstTick)).toEqual(['x!', 'y!']);
    expect(await Promise.all(secondTick)).toEqual(['y!', 'z!']);
  });
});

